#Installs Winget and Firefox
#----------------------------------------------------------------------------
&{
    if( [System.Environment]::OSVersion.Version.Build -lt 26100 ) {
        'This script requires Windows 11 24H2 or later.' | Write-Warning;
        return;
    }
    $timeout = [datetime]::Now.AddMinutes( 5 );
    $exe = "$env:LOCALAPPDATA\Microsoft\WindowsApps\winget.exe";

    while( $true ) {
        if( $exe | Test-Path ) {
            & $exe install --exact --id Mozilla.Firefox --silent --accept-package-agreements --accept-source-agreements --source winget --scope machine;
            return;
        }
        if( [datetime]::Now -gt $timeout ) {
            "File '${exe}' does not exist." | Write-Warning;
            return;
        }
        "Waiting for '${exe}' to become available..." | Write-Host;
        Start-Sleep -Seconds 1;
    }
}

#Copies preferences and policies files from USB to the Firefox installation
#----------------------------------------------------------------------------
foreach( $drive in [System.IO.DriveInfo]::GetDrives() ) {
    if( $found = Join-Path -Path $drive.RootDirectory -ChildPath 'Windows*installation*extras\Mozilla*Firefox' -Resolve -ErrorAction 'SilentlyContinue' ) {
        $firefoxPath = (Get-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\App Paths\firefox.exe").'(Default)';
        $firefoxDir = Split-Path -Path $firefoxPath;
        Copy-Item -Path "$found\*" -Destination $firefoxDir -Recurse -Force;
        return;
    }
}
'Cannot find any files that match pattern.' | Write-Warning;

